/**
 * AzbkROMs.js - Встроенные прошивки и ресурсы контроллера AZBK
 * Сгенерировано из reference/Release_x64/AZBK/ROM/
 */
(function() {
  function b64ToUint8(b64) {
    var bin = (typeof atob !== "undefined") ? atob(b64) : Buffer.from(b64, "base64").toString("binary");
    var u8 = new Uint8Array(bin.length);
    for (var i = 0; i < bin.length; i++) {
      u8[i] = bin.charCodeAt(i);
    }
    return u8;
  }

  var AzbkROMs = {
    "azboot_ROM": b64ToUint8(""),
    "AZLIB00_ROM": b64ToUint8(""),
    "AZLIB01_ROM": b64ToUint8(""),
    "AZLIB02_ROM": b64ToUint8(""),
    "AZLIB03_ROM": b64ToUint8(""),
    "AZ337_ROM": b64ToUint8(""),
    "SETUP_ROM": b64ToUint8(""),
    "AZLOGO_RAW": b64ToUint8(""),
  };

  AzbkROMs.azboot = AzbkROMs.azboot_ROM;
  AzbkROMs.azlib00 = AzbkROMs.AZLIB00_ROM;
  AzbkROMs.azlib01 = AzbkROMs.AZLIB01_ROM;
  AzbkROMs.azlib02 = AzbkROMs.AZLIB02_ROM;
  AzbkROMs.azlib03 = AzbkROMs.AZLIB03_ROM;
  AzbkROMs.az337 = AzbkROMs.AZ337_ROM;
  AzbkROMs.setup = AzbkROMs.SETUP_ROM;

  if (typeof module !== "undefined" && module.exports) {
    module.exports = AzbkROMs;
  }
  if (typeof window !== "undefined") {
    window.AzbkROMs = AzbkROMs;
  }
})();
